// Helper to get title with fallback
export const getWeekTitle = (weekId, lang = 'en') => {
  const meta = weekTitles[weekId];
  if (meta) {
    return lang === 'vi' ? meta.title_vi : meta.title_en;
  }
  return lang === 'vi' ? `Tuần ${weekId}` : `Week ${weekId}`;
};
